import AppKit
import TackCore

/// Polls the general pasteboard while started and turns every foreign copy into a (not yet stored) history item.
@MainActor
final class ClipboardMonitor {
    var onItem: ((HistoryItem) -> Void)?

    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
    ]
    private static let ignoredApps: Set<String> = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.agilebits.onepassword-osx",
        "com.agilebits.onepassword4",
        "com.bitwarden.desktop",
        "com.lastpass.LastPass",
        "com.lastpass.lastpassmacdesktop",
        "com.dashlane.Dashlane",
        "com.dashlane.dashlanephonefinal",
    ]
    private static let maxImagePixels = 40_000_000

    private let clipsDirectory: URL
    private var lastChangeCount = NSPasteboard.general.changeCount
    private var timer: Timer?

    init(clipsDirectory: URL) {
        self.clipsDirectory = clipsDirectory
    }

    func start() {
        stop()
        lastChangeCount = NSPasteboard.general.changeCount
        let timer = Timer(timeInterval: 0.3, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.poll() }
        }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    func flush() {
        guard timer != nil else { return }
        poll()
    }

    private func poll() {
        let pasteboard = NSPasteboard.general
        let changeCount = pasteboard.changeCount
        guard changeCount != lastChangeCount else { return }
        lastChangeCount = changeCount
        guard !Clipboard.isOwnWrite(pasteboard) else { return }
        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.ignoredTypes) else { return }
        let frontmost = NSWorkspace.shared.frontmostApplication
        if let bundleID = frontmost?.bundleIdentifier, Self.ignoredApps.contains(bundleID) { return }
        if let item = read(pasteboard, sourceApp: frontmost?.localizedName) {
            onItem?(item)
        }
    }

    private func read(_ pasteboard: NSPasteboard, sourceApp: String?) -> HistoryItem? {
        if let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty {
            return .files(urls.map(\.path), sourceApp: sourceApp)
        }
        if let image = readImage(pasteboard, sourceApp: sourceApp) {
            return image
        }
        if let text = pasteboard.string(forType: .string), !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return .text(text, sourceApp: sourceApp)
        }
        return nil
    }

    private func readImage(_ pasteboard: NSPasteboard, sourceApp: String?) -> HistoryItem? {
        let png: Data
        if let data = pasteboard.data(forType: .png) {
            guard let size = ImageFiles.pixelSize(of: data), size.pixels <= Self.maxImagePixels else { return nil }
            png = data
        } else if let data = pasteboard.data(forType: .tiff) {
            guard let size = ImageFiles.pixelSize(of: data), size.pixels <= Self.maxImagePixels,
                  let converted = ImageFiles.pngData(from: data)
            else { return nil }
            png = converted
        } else {
            return nil
        }
        guard let size = ImageFiles.pixelSize(of: png) else { return nil }
        let url = ImageFiles.newPNGURL(in: clipsDirectory, prefix: "clip")
        do {
            try png.write(to: url, options: .atomic)
        } catch {
            NSLog("Tack: could not save clipboard image: \(error.localizedDescription)")
            return nil
        }
        return .image(path: url.path, size: size, screenshot: false, sourceApp: sourceApp)
    }
}
